SELECT percentile_cont(0.85) within GROUP (ORDER BY length_of_stay) AS instability_score_percentile, male_icu_patients.hadm_id, male_icu_patients.stay_id, male_icu_patients.intime, male_icu_patients.outtime, male_icu_patients.los, male_icu_patients.icd_code, male_icu_patients.icd_version FROM male_icu_patients JOIN instability_scores ON male_icu_patients.hadm_id = instability_scores.hadm_id WHERE male_icu_patients.anchor_age = 93 ORDER BY length_of_stay DESC LIMIT 1;